import { useEffect, useState } from 'react';
import { ArrowUpRight, Database, History, Trash2 } from 'lucide-react';
import type {
  ApprovedSource,
  ApprovedSourceDetail,
  ApprovedManifest,
  FinalReceipt,
  ImportJob,
